# -*- coding: utf-8 -*-
"""Builds public/prototype-v21-notes.html (reviewer notes) from data/issues.json and the before/after shots in public/images/v21/notes/."""
import json, html, collections, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PUB = os.path.join(os.path.dirname(ROOT), 'public')
iss = json.load(open(os.path.join(ROOT, 'data/issues.json'), encoding='utf-8'))
vs = collections.Counter(x['v21']['status'] for x in iss)
style = open(os.path.join(PUB, 'prototype-v20-notes.html'), encoding='utf-8').read()
style = style[style.index('<style>'):style.index('</style>') + 8].replace('--acc:#E01A3E', '--acc:#DF234A')
pairs = [('tabs-p07', 'Вкладки не обрезаются', 'В «Доступах» на 320 px было «Открыто … / Открыто …». Теперь подписи целиком, ряд прокручивается вбок.'),
 ('me-tabs', '«Я»: вкладки и точки', 'Точки «новое» стоят на своих вкладках, подписи 14 px не слипаются; заголовки — Geologica.'),
 ('pair-entry', 'Вход в пару из «Я → Моё»', 'Раньше создать пару можно было только через QA-панель. Теперь — строка «Пара» со всеми состояниями.'),
 ('feed-us-following', '«Подписки» в режиме «Мы»', 'Раньше лента пары показывала подписки Alex. Теперь — подписки самой пары.'),
 ('event-going', 'Событие: честные «Идут»', 'Счётчики «Идут / Интересуются» из реальных данных, ожидающая заявка не показывается как «идёт».'),
 ('settings', 'Настройки', '«Проверка возраста» открывается, есть «Приватность и видимость», «Пара» и «Скрытое в ленте».'),
 ('toast-sheet', 'Тосты над листами', 'Тост больше не закрывает кнопку «Удалить навсегда» — при открытом листе он вверху.'),
 ('chat-head', 'Шапка чата', 'Имя и статус на стеклянной подложке — сообщения не просвечивают.'),
 ('dock-320', 'Док на 320 px', '«Сообщества» помещается целиком.')]
fig = lambda v, n, c: f'<figure><img src="images/v21/notes/{v}-{n}.webp" alt="" loading="lazy"><figcaption>{c}</figcaption></figure>'
shots = ''.join(f'<h3>{html.escape(t)}</h3><p>{html.escape(d)}</p><div class="shots wide">{fig("v20", n, "V20")}{fig("v21", n, "V21")}</div>' for n, t, d in pairs)
rest = [x for x in iss if x['v21']['status'] in ('needs-owner', 'partial')]
rows = ''.join(f'<tr><td><code>{x["id"]}</code></td><td>{html.escape(x["v21"]["label"])}</td><td>{html.escape(x["v21"]["what"])}</td></tr>' for x in rest)
dec = [('Шрифт', 'Заголовки — Geologica, текст — Onest.'), ('Акцент', '#DF234A; в тёмной теме кнопки тоже #DF234A, красный текст светлее (#FF4566).'),
       ('Знакомства', 'Все по умолчанию в знакомствах (человек и пара); без фото в подборке не видно. Онбординг говорит это и предлагает фото или выключить знакомства.'),
       ('Интересы по доступу', 'Открываются вместе с «Описанием».'), ('Тесты', 'Убраны.'), ('«Я/Мы» в доке', 'Открывает «Действовать как» — как было.'),
       ('Условия и политика', 'В прототипе — выжимки; финальные тексты задаются в админке.'), ('«Как видят»', 'Настоящий блок «Что у вас общего» на примере зрителя.'),
       ('Premium-подарок паре (#1277)', 'Получают оба партнёра, цена за двоих.'), ('Приватная часть пары (#1277)', 'Открывается только вдвоём: партнёр подтверждает всегда.')]
dtab = ''.join(f'<tr><td>{html.escape(a)}</td><td>{html.escape(b)}</td></tr>' for a, b in dec)
doc = f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>FetUre V21 — что изменено</title>{style}</head><body><main>
<a class="cta" href="prototype-v21.html#X01">Открыть V21 →</a><a class="cta soft" href="prototype-v20.html#X01">V20</a>
<h1>FetUre V21 — исправления по аудиту V20</h1>
<p class="lead">V21 — это V20 с исправлениями полного UX/UI-аудита и изменениями V20 #1277: {len(iss)} проблем, исправлено {vs["fixed"]}, частично {vs["partial"]}, не воспроизвелись {vs["not-reproduced"]}, решено владельцем оставить {vs["wont-fix"]}, перенесено в спецификацию React/админку {vs["spec"]}. V20 не меняется.</p>
<p>Журнал — <code>docs/design-reference/V21-CHANGELOG.md</code>. Статус по каждому пункту — <code>apps/feture/audit-v20/V21-FIX-STATUS.md</code>, интерактивный отчёт — <code>apps/feture/audit-v20/report.html</code>. Перенос в React — <code>docs/design-reference/V21-INTEGRATION-GUIDE.md</code>.</p>
<h2>Решения владельца</h2><table><tr><th>Вопрос</th><th>Решение</th></tr>{dtab}</table>
<h2>Главное</h2>
<ul><li><b>«Я / Мы» в данных:</b> подписки, голоса в опросах, блокировки, черновики, организатор событий и сообществ, участие в закрытых сообществах, «Нужно решить» партнёра — всё от действующего профиля.</li>
<li><b>Пара:</b> создать пару можно из «Я → Моё» и Настроек; новая пара начинается пустой; приглашение видно и отзывается; остановленная пара восстанавливается.</li>
<li><b>Приватность:</b> ответы шага «О тебе» по умолчанию «Только ты»; выключение приватной части отзывает доступы и закрывает запросы; «Смотрю незаметно» не включает показ.</li>
<li><b>Навигация и компоненты:</b> «‹» не уводит в другую вкладку; вкладки не обрезаются; листы закрываются свайпом; тосты не перекрывают кнопки; единые диалоги и кнопка «+».</li>
<li><b>Тихие кнопки ожили:</b> «Сделать главным», «Проверка возраста», лайк ответа не участником (теперь объясняет), «Рядом» в фильтрах, «Изменить решение» по событию пары.</li></ul>
<h2>Было → стало</h2>{shots}
<h2>Частично</h2><table><tr><th>ID</th><th>Статус</th><th>Что сделано</th></tr>{rows}</table>
<h2>Проверено</h2><p>Контракты V20 и V21 проходят. Полный обход всех экранов QA-панели для трёх персон — без JS-ошибок, без «undefined/NaN», без горизонтальной прокрутки. Повторный краулер по всем кнопкам и 75 попапам — 0 мёртвых обработчиков. Матрица 320–1920 — 0 переполнений. Все P0 перепроверены вручную.</p>
<p>Не проверено: реальные устройства и касания, экранная клавиатура, оплата, живая пара на двух устройствах.</p>
</main></body></html>'''
open(os.path.join(PUB, 'prototype-v21-notes.html'), 'w', encoding='utf-8').write(doc)
print('notes', len(doc))
